        {stats([["联系人",data.customers.filter(c => c.contact).length],["电话跟进",data.followups.filter(f => f.method === "电话").length],["待回访",activeTasks.length]])}
        <div className="phone-tabs"><button className={phoneTab === "contacts" ? "active" : ""} onClick={() => setPhoneTab("contacts")}>联系人</button><button className={phoneTab === "records" ? "active" : ""} onClick={() => setPhoneTab("records")}>通话记录</button></div>
        {phoneTab === "contacts" ? <>
          {data.customers.filter(c => [c.contact,c.name,c.phone].join(" ").toLowerCase().includes(search.toLowerCase())).map(c => <div className="contact-row" key={c.id}><span className="person-avatar">{(c.contact || c.name).slice(0,1)}</span><button className="contact-info" onClick={() => open("customer",c.id)}><strong>{c.contact || "联系人待补充"}</strong><small>{c.name}</small>{c.phone && <small>{c.phone}</small>}</button>{c.phone && !c.demo ? <a className="call-button" href={`tel:${c.phone.replace(/[^+\d]/g,"")}`} aria-label={`拨打${c.contact}的电话`}><Phone size={21} /></a> : <button className="call-button muted" aria-label="补充联系电话" onClick={() => open("customerForm",c.id)}><PencilLine size={20} /></button>}</div>)}
          {!data.customers.filter(c => [c.contact,c.name,c.phone].join(" ").toLowerCase().includes(search.toLowerCase())).length && <Empty title={search ? "未找到联系人" : "暂无联系人"} description={search ? "试试其他姓名、客户名称或电话号码" : "新增客户并填写联系人后，即可在这里拨号"} icon={Phone} action={newButton("customerForm","添加联系人")} />}
        </> : <>
          {data.followups.filter(f => f.method === "电话" && [nameOf(f.customerId),f.content].join(" ").toLowerCase().includes(search.toLowerCase())).map(f => <button className="timeline-card" key={f.id} onClick={() => open("customer",f.customerId)}><div><Badge>电话跟进</Badge><small>{when(f.createdAt)}</small></div><strong>{nameOf(f.customerId)}</strong><p>{f.content}</p></button>)}
          {!data.followups.filter(f => f.method === "电话" && [nameOf(f.customerId),f.content].join(" ").toLowerCase().includes(search.toLowerCase())).length && <Empty title="暂无通话记录" description="完成通话后，使用写跟进保存沟通内容" icon={Phone} action={newButton("followup","写跟进")} />}
        </>}
        <p className="info-note"><ShieldCheck size={16} />手机拨号，手动记录电话跟进。</p>
